    $data['source_details'] = json_decode($old['source_snapshot'], true)['details'] ?? '';
}
$kind = $data['kind_code'] ?? 'recovery';
?>
<section class="section"><h1><?= $old === null ? 'Record documented recovery' : 'Correct recovery with a same-source replacement' ?></h1>
<p><a href="<?= $base ?>">Back to work job</a></p><p>Record actual received or returned money supported by private evidence. Turo recognition is unavailable. One receipt must belong wholly to this job; mixed-job payments cannot be split here.</p>
