<form data-recovery-form action="<?= $base . ($old === null ? '/recoveries' : '/recoveries/' . (int) $old['id'] . '/replace') ?>" method="post" enctype="multipart/form-data"><?= csrf_field() ?><?= view('vehicle_damage_repairs/_command', ['workAction' => $old === null ? 'b31_record' : 'b31_replace']) ?><input type="hidden" name="authority_code" value="external_receipt">
<?php if ($old !== null): ?><input type="hidden" name="recovery_entry_id" value="<?= (int) $old['id'] ?>"><input type="hidden" name="expected_entry_state" value="<?= esc($repairRecoveries['entry_states'][$old['id']] ?? '', 'attr') ?>"><label>Correction reason<textarea name="reason" required maxlength="2000"><?= esc((string) ($data['reason'] ?? '')) ?></textarea></label><?php endif; ?>
