<label>Source type<select name="source_type"><?php foreach (\Config\VehicleDamageRepairRecoveries::SOURCES as $code => $label): if ($code === 'turo_reimbursement') { continue; } ?><option value="<?= esc($code, 'attr') ?>" <?= ($data['source_type'] ?? 'guest_direct') === $code ? 'selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
<label>Actual amount<input name="amount" required inputmode="decimal" value="<?= esc((string) ($data['amount'] ?? ''), 'attr') ?>"></label><label>Currency<select name="currency"><option value="USD">USD</option></select></label>
<label>Received / returned on<input type="date" name="occurred_on" required value="<?= esc((string) ($data['occurred_on'] ?? ''), 'attr') ?>"></label><label>Payer name from evidence<input name="payer_snapshot" required maxlength="190" value="<?= esc((string) ($data['payer_snapshot'] ?? ''), 'attr') ?>"></label>
<label>Payment namespace<input name="source_namespace" required maxlength="120" placeholder="bank_transfer:account-token" value="<?= esc((string) ($data['source_namespace'] ?? ''), 'attr') ?>"></label><label>Stable receipt / reversal reference<input name="source_reference" required maxlength="120" value="<?= esc((string) ($data['source_reference'] ?? ''), 'attr') ?>"></label>
