<label>Claim context (optional)<select name="damage_claim_id"><option value="">No claim association</option><?php foreach ($recoveryClaims as $claim): ?><option value="<?= (int) $claim['id'] ?>" <?= (string) ($data['damage_claim_id'] ?? '') === (string) $claim['id'] ? 'selected' : '' ?>><?= esc($claim['claim_number'] ?? 'Claim linked to this job') ?></option><?php endforeach; ?></select></label>
<label>Existing private evidence<select name="repair_document_id"><option value="">New upload</option><?php foreach ($repairDocuments as $doc): if ($doc['archived_at'] !== null || ! in_array($doc['kind_code'], \Config\VehicleDamageRepairRecoveries::DOCUMENT_KINDS, true)) { continue; } ?><option value="<?= (int) $doc['id'] ?>" <?= (string) ($data['repair_document_id'] ?? '') === (string) $doc['id'] ? 'selected' : '' ?>><?= esc(\Config\VehicleDamageRepairDocuments::KINDS[$doc['kind_code']]) ?> / <?= esc($doc['label'] ?? $doc['content_original_filename']) ?></option><?php endforeach; ?></select></label>
<label>New private evidence<input type="file" name="repair_document" accept="application/pdf,image/jpeg,image/png,image/webp"></label><label>Evidence label<input name="document[label]" maxlength="190" value="<?= esc((string) ($data['document']['label'] ?? ''), 'attr') ?>"></label>
</div>
