<label>Receipt provenance and job scope<textarea name="source_details" required maxlength="2000"><?= esc((string) ($data['source_details'] ?? '')) ?></textarea></label><label>Note<textarea name="note" maxlength="2000"><?= esc((string) ($data['note'] ?? '')) ?></textarea></label>
<?php foreach (['received_confirmed' => 'Incoming receipt: the money was actually received.', 'returned_confirmed' => 'Reversal: money was actually returned or clawed back.', 'whole_job_confirmed' => 'This payment belongs wholly to this job, with no multi-job or mixed-purpose allocation.', 'outside_turo_confirmed' => 'This payment was received outside Turo and is not represented by a Turo transaction.', 'not_cost_reduction_confirmed' => 'This is not a vendor invoice credit or vendor payment refund recorded in repair costs.', 'not_duplicate_confirmed' => 'This payment is not already represented by another recovery lineage.', 'claim_context_confirmed' => 'If a claim is selected, I verified its explicit damage-condition relationship to this job.'] as $field => $label): ?><label><input type="checkbox" name="<?= $field ?>" value="1" <?= ($data[$field] ?? '') === '1' ? 'checked' : '' ?>> <?= esc($label) ?></label><?php endforeach; ?>
